query SimulcastRaceInfo($ids: [String!], $raceNumber: String, $meetingDate: String, $venCode: String) {
  simulcastHorse(ids: $ids, raceNumber: $raceNumber, meetingDate: $meetingDate, venCode: $venCode) {
    id
    horseFormRecord {
      id
      date
      jockey {
        code
        name_ch
        name_en
      }
      trainer {
        name_ch
        name_en
      }
      raceNo
      placeNo
      ruPlace
      venue {
        code
        chinese
        english
      }
      track {
        english
        chinese
        code
      }
      gear
      comments {
        code
        chinese
        english
      }
      winners{
        pos
        name {
          chinese
          english
        }
        cnty {
          code
          chinese
          english
        }
      }
      med {
        code
        chinese
        english
      }
      raceName {
        code
        chinese
        english
      }
      course {
        code
        chinese
        english
      }
      raceId
      raceIndex
      runnerStatus
      racingComments {
        name
        date
      }
      winOdds
      resultIndex
      horseWeight
      actualWeight
      marginOrLBW {
        code
        chinese
        english
      }
      season
      runnerResults {
        id
      }
      racecourse {
        code
        chinese
        english
      }
      going {
        code
        chinese
        english
      }
      sectionTimeSplits {
        sectionTime
        gpSec
        sectionNo
      }
      raceTimeSplits {
        sectionNo
        gpSec
        sectionTime
      }
      sectionInfos {
        sectionNo
        ruPos
        sectionTime
      }
      barrierDrNo
      distance
      finalTimeOfRace
      raceCountry {
        code
        chinese
        english
      }
      cntyShortNm {
        code
        chinese
        english
      }
      racecourse {
        code
        chinese
        english
      }
      numOfStarters
      currency {
        english
        code
        chinese
      }
      ageCondition {
        code
        english
        chinese
      } 
      condition {
        code
        english
        chinese
      }
      prizeMoney
      fav
      placingRemarks
      className {
        chinese
        code
        english
      }
      raceTurn {
        chinese
        code
        english
      }
    }
    brandNumber
  }
}
